    const state = makeState(world);
    const { deps, events } = makeDeps();
    // 400 m/s × 0.05 s = 20 blocks/step — would skip the wall without the swept DDA.
    spawnArrow(state, 12, 12, 12, new THREE.Vector3(0, 0, -1), { speed: 400, damage: 5, knockback: 0, fromPlayer: true, ttl: 4 });

