1	import * as THREE from "three";
2	import { voxelRaycast } from "@/lib/world";
3	import { ARROW_GRAVITY, ARROW_HIT_RADIUS, ARROW_MAX_SEGMENT, ARROW_MAX_SUBSTEPS, PLAYER_HALF_WIDTH, PLAYER_HEIGHT } from "@/lib/game/config";
4	import type { EmitGameEvent, GameState, MobState } from "../state";
5	
6	export type ProjectileTickDeps = {
7	  applyDamage: (amount: number) => void;
8	  removeMobAt: (index: number) => void;
9	  emit: EmitGameEvent;
10	};
11	
12	// Scratch vectors — the tick runs every frame over every arrow and must not allocate.
13	const segDir = new THREE.Vector3();
14	const knock = new THREE.Vector3();
15	
16	/**
17	 * Distance along the unit-direction segment [origin, origin + dir*len] of the
18	 * point on it closest to (px, py, pz), clamped to the segment endpoints.
19	 */
20	function closestParam(ox: number, oy: number, oz: number, dx: number, dy: number, dz: number, len: number, px: number, py: number, pz: number): number {
21	  const t = (px - ox) * dx + (py - oy) * dy + (pz - oz) * dz;
22	  return t < 0 ? 0 : t > len ? len : t;
23	}
24	
25	// A boss body is far wider than the default padding suits, so widen the hit
26	// cylinder for tall mobs; ordinary mobs keep the tight 0.45 padding.
27	function mobBodyRadius(mob: MobState): number {
28	  return ARROW_HIT_RADIUS + (mob.halfHeight > 1.4 ? 0.9 : 0);
29	}
30	
31	/**
32	 * Advances every in-flight arrow. Each arrow integrates under gravity in capped
33	 * substeps so a fast shot can't skip a 1-block wall or a thin mob: per substep
34	 * it sweeps the world DDA for a block hit and tests the segment against the
35	 * relevant entity (mobs for player arrows, the player for mob arrows), resolving
36	 * whichever is nearer. Spent arrows (hit, expired, or out of bounds) despawn.
37	 */
38	export function tickProjectiles(state: GameState, dt: number, deps: ProjectileTickDeps): void {
39	  const { world, projectiles } = state;
40	  if (projectiles.length === 0) return;
41	  const dead: number[] = [];
42	
43	  for (let i = 0; i < projectiles.length; i += 1) {
44	    const p = projectiles[i];
45	    p.ttl -= dt;
46	    if (p.ttl <= 0) {
47	      dead.push(i);
48	      continue;
49	    }
50	
51	    const substeps = Math.min(ARROW_MAX_SUBSTEPS, Math.max(1, Math.ceil((p.velocity.length() * dt) / ARROW_MAX_SEGMENT)));
52	    const sdt = dt / substeps;
53	    let removed = false;
54	
55	    for (let s = 0; s < substeps && !removed; s += 1) {
56	      p.velocity.y -= ARROW_GRAVITY * sdt;
57	      const segLen = p.velocity.length() * sdt;
58	      if (segLen < 1e-9) continue;
59	      segDir.copy(p.velocity).divideScalar(p.velocity.length());
60	
61	      // Swept block collision (reuses the world DDA used for mining/line-of-sight).
62	      let blockT = Number.POSITIVE_INFINITY;
63	      const blockHit = voxelRaycast(world, p.position, segDir, segLen);
64	      if (blockHit && blockHit.distance <= segLen) blockT = blockHit.distance;
65	
66	      // Nearest entity along the segment.
67	      let entityT = Number.POSITIVE_INFINITY;
68	      let hitMobIndex = -1;
69	      if (p.fromPlayer) {
70	        for (let m = 0; m < state.mobs.length; m += 1) {
71	          const mob = state.mobs[m];
72	          const t = closestParam(
73	            p.position.x,
74	            p.position.y,
75	            p.position.z,
76	            segDir.x,
77	            segDir.y,
78	            segDir.z,
79	            segLen,
80	            mob.position.x,
81	            mob.position.y,
82	            mob.position.z
83	          );
84	          const horiz = Math.hypot(p.position.x + segDir.x * t - mob.position.x, p.position.z + segDir.z * t - mob.position.z);
85	          const vert = Math.abs(p.position.y + segDir.y * t - mob.position.y);
86	          if (horiz <= mobBodyRadius(mob) && vert <= mob.halfHeight + ARROW_HIT_RADIUS && t < entityT) {
87	            entityT = t;
88	            hitMobIndex = m;
89	          }
90	        }
91	      } else {
92	        const feet = state.player.position;
93	        const midY = feet.y + PLAYER_HEIGHT / 2;
94	        const t = closestParam(p.position.x, p.position.y, p.position.z, segDir.x, segDir.y, segDir.z, segLen, feet.x, midY, feet.z);
95	        const horiz = Math.hypot(p.position.x + segDir.x * t - feet.x, p.position.z + segDir.z * t - feet.z);
96	        const vert = Math.abs(p.position.y + segDir.y * t - midY);
97	        if (horiz <= PLAYER_HALF_WIDTH + ARROW_HIT_RADIUS && vert <= PLAYER_HEIGHT / 2 + ARROW_HIT_RADIUS) entityT = t;
98	      }
99	
100	      if (entityT !== Number.POSITIVE_INFINITY && entityT <= blockT) {
101	        const hx = p.position.x + segDir.x * entityT;
102	        const hy = p.position.y + segDir.y * entityT;
103	        const hz = p.position.z + segDir.z * entityT;
104	        if (p.fromPlayer) {
105	          const mob = state.mobs[hitMobIndex];
106	          mob.hp -= p.damage;
107	          knock.set(segDir.x, 0, segDir.z);
108	          if (knock.lengthSq() > 1e-6) {
109	            knock.normalize();
110	            mob.direction.copy(knock);
111	            mob.position.addScaledVector(knock, p.knockback);
112	            mob.position.y += 0.1;
113	          }
114	          deps.emit({ type: "mobHit", kind: mob.kind });
115	          deps.emit({ type: "arrowHit", x: hx, y: hy, z: hz, target: "mob" });
116	          if (mob.hp <= 0) deps.removeMobAt(hitMobIndex);
117	        } else {
118	          deps.applyDamage(p.damage);
119	          state.player.velocity.x += segDir.x * p.knockback;
120	          state.player.velocity.z += segDir.z * p.knockback;
121	          deps.emit({ type: "arrowHit", x: hx, y: hy, z: hz, target: "player" });
122	        }
123	        removed = true;
124	      } else if (blockT !== Number.POSITIVE_INFINITY) {
125	        deps.emit({
126	          type: "arrowHit",
127	          x: p.position.x + segDir.x * blockT,
128	          y: p.position.y + segDir.y * blockT,
129	          z: p.position.z + segDir.z * blockT,
130	          target: "block"
131	        });
132	        removed = true;
133	      } else {
134	        p.position.addScaledVector(segDir, segLen);
135	      }
136	    }
137	
138	    if (!removed) {
139	      const speed = p.velocity.length();
140	      p.yaw = Math.atan2(p.velocity.x, p.velocity.z);
141	      p.pitch = Math.asin(speed > 1e-6 ? Math.max(-1, Math.min(1, p.velocity.y / speed)) : 0);
142	      if (
143	        p.position.x < 1 ||
144	        p.position.z < 1 ||
145	        p.position.x > world.sizeX - 1 ||
146	        p.position.z > world.sizeZ - 1 ||
147	        p.position.y < 0 ||
148	        p.position.y > world.sizeY
149	      ) {
150	        removed = true;
151	      }
152	    }
153	    if (removed) dead.push(i);
154	  }
155	
156	  for (let i = dead.length - 1; i >= 0; i -= 1) projectiles.splice(dead[i], 1);
157	}

15	
16	const scratchDir = new THREE.Vector3();
17	
18	/**
19	 * Launches an arrow from (originX, originY, originZ) along `dir`. The single
20	 * launch path shared by the player's bow, ranged skeletons, and the boss.
21	 * Returns the created projectile (handy for tests).
22	 */
23	export function spawnArrow(state: GameState, originX: number, originY: number, originZ: number, dir: THREE.Vector3, opts: SpawnArrowOptions): ProjectileState {
24	  scratchDir.copy(dir);
25	  if (scratchDir.lengthSq() < 1e-9) scratchDir.set(0, 0, -1);
